1225	bool XRef::getStreamEnd(Goffset streamStart, Goffset *streamEnd) {
1226	  int a, b, m;
1227	
1228	  if (streamEndsLen == 0 ||
1229	      streamStart > streamEnds[streamEndsLen - 1]) {
1230	    return false;
1231	  }
1232	
1233	  a = -1;
1234	  b = streamEndsLen - 1;
1235	  // invariant: streamEnds[a] < streamStart <= streamEnds[b]
1236	  while (b - a > 1) {
